"""Vocabulary-based typo correction for search queries and addresses.

Only whole alphabetic tokens that are absent from the catalog vocabulary are touched.
Each is replaced by the closest vocabulary word (Damerau-Levenshtein, at most one edit
for tokens up to six characters and two edits for longer ones), with ties broken by
catalog frequency. Digits, short tokens (under five letters), and words already in the
vocabulary are kept, as is any token that is a prefix of a vocabulary word (the user is still
typing; the engine matches prefixes). A candidate must share the first letter and occur at least 30 times in
the catalog or belong to the explicit brand allowlist; these guards eliminate harmful false-positive fixes
(`pigroup` to `group`, `lexi` to `levi`, `halalmart` to `hallmark`).
"""

from __future__ import annotations

import lzma
import re
from bisect import bisect_left
from collections.abc import Iterable, Iterator, Mapping
from functools import lru_cache
from pathlib import Path
from typing import Any, Final

from rapidfuzz.distance import DamerauLevenshtein
from rapidfuzz.process import extract

from ..grammar.sanitizers import VOCAB_ALPHA_WORD_RE as _ALPHA_WORD_RE
from .text_utils import build_term_automaton, replace_terms_automaton
from .unicode import normalize_ascii

_SHORT_TOKEN_MAX_EDITS: Final = 1
_LONG_TOKEN_MAX_EDITS: Final = 2
_SHORT_TOKEN_LENGTH: Final = 6
_CANDIDATE_LIMIT: Final = 8

_ARTIFACT_DIR: Final[Path] = Path(__file__).resolve().parents[1] / "artifacts"


def _register_brand_allowlist(vocab: dict[str, int], brands: Iterable[str]) -> None:
    """Ensure all allowlisted brand words exist in vocabulary with candidate frequency floor."""
    for w in brands:
        vocab[w] = max(vocab.get(w, 0), 100)


def _register_canonical_targets(vocab: dict[str, int], targets: Iterable[str]) -> None:
    """Ensure constituent words of canonical targets exist in vocabulary with candidate floor."""
    for target in targets:
        for word in target.split():
            w_norm = normalize_ascii(word).lower()
            if w_norm:
                vocab[w_norm] = max(vocab.get(w_norm, 0), 100)


def iter_vocab_tokens(text: str) -> Iterator[str]:
    """Yield ASCII-folded, lower-cased alphabetic words of two or more letters."""
    for match in _ALPHA_WORD_RE.finditer(text):
        yield normalize_ascii(match.group()).lower()


def write_vocab(path: Path, counts: Mapping[str, int]) -> None:
    """Write ``word<TAB>count`` lines, most frequent first."""
    path.parent.mkdir(parents=True, exist_ok=True)
    lines = (f"{word}\t{count}" for word, count in sorted(counts.items(), key=lambda kv: -kv[1]))
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def load_vocab(path: Path) -> dict[str, int]:
    """Read a vocabulary written by :func:`write_vocab` or compressed with .xz."""
    raw = (
        lzma.decompress(path.read_bytes()).decode("utf-8")
        if path.suffix == ".xz"
        else path.read_text(encoding="utf-8")
    )
    return {
        w: int(c)
        for line in raw.splitlines()
        for w, _, c in (line.partition("\t"),)
        if w and c.isdigit()
    }


def load_lexicon(path: Path) -> dict[str, str]:
    """Read a typo-to-target lexicon (word<TAB>target) compressed with .xz or plain."""
    raw = (
        lzma.decompress(path.read_bytes()).decode("utf-8")
        if path.suffix == ".xz"
        else path.read_text(encoding="utf-8")
    )
    return {
        t.strip(): target.strip()
        for line in raw.splitlines()
        for t, _, target in (line.partition("\t"),)
        if t and target
    }


class QueryCorrector:
    """Replace out-of-vocabulary alphabetic tokens with their closest catalog word."""

    def __init__(
        self,
        vocab: Mapping[str, int],
        *,
        min_token_length: int = 5,
        min_candidate_count: int = 30,
        min_prefix_count: int = 5,
        brand_allowlist: frozenset[str] | None = None,
        lexicon: Mapping[str, str] | None = None,
    ) -> None:
        self._brand_allowlist = brand_allowlist or frozenset()
        self._vocab = dict(vocab)
        _register_brand_allowlist(self._vocab, self._brand_allowlist)
        self._lexicon = dict(lexicon) if lexicon else {}
        _register_canonical_targets(self._vocab, self._lexicon.values())
        self._lexicon_automaton = build_term_automaton(self._lexicon) if self._lexicon else None
        self._min_token_length = min_token_length
        self._min_prefix_count = min_prefix_count
        self._known_words = {
            w
            for w, count in self._vocab.items()
            if count >= min_prefix_count or w in self._brand_allowlist
        }
        self._prefix_words = sorted(self._known_words)
        self._sorted_words = self._prefix_words
        self._words_by_start_and_length: dict[tuple[str, int], list[str]] = {}
        for word, count in self._vocab.items():
            if count >= min_candidate_count or word in self._brand_allowlist:
                self._words_by_start_and_length.setdefault((word[0], len(word)), []).append(word)
        self._nearest = lru_cache(maxsize=65_536)(self._nearest_uncached)

    @classmethod
    def from_file(
        cls,
        path: Path,
        *,
        lexicon_path: Path | None = None,
        **kwargs: Any,
    ) -> QueryCorrector:
        """Load vocabulary file; optionally load empirical typo lexicon."""
        if not path.is_file():
            raise FileNotFoundError(f"Query vocabulary not found: {path}")
        vocab = load_vocab(path)
        lexicon = load_lexicon(lexicon_path) if lexicon_path and lexicon_path.is_file() else None
        return cls(vocab, lexicon=lexicon, **kwargs)

    @classmethod
    def load_packaged_lexicon(cls) -> QueryCorrector | None:
        """Load default packaged vocabulary artifact from ``vihap/artifacts/`` if present."""
        for name in ("query_lexicon.tsv.xz", "query_lexicon.tsv", "vocab.tsv.xz", "vocab.tsv"):
            candidate = _ARTIFACT_DIR / name
            if candidate.is_file():
                return cls.from_file(candidate)
        return None

    def correct(self, text: str) -> str:
        """Return ``text`` with misspelled alphabetic tokens replaced."""
        if not text:
            return "" if text is None else text
        if self._lexicon_automaton is not None:
            text = replace_terms_automaton(text, self._lexicon_automaton)
        return _ALPHA_WORD_RE.sub(self._replace, text)

    def _replace(self, match: re.Match[str]) -> str:
        token = match.group()
        folded = normalize_ascii(token).lower()
        if folded in self._lexicon:
            return self._lexicon[folded]
        if (
            len(folded) < self._min_token_length
            or folded in self._brand_allowlist
            or self._is_known_or_prefix(folded)
        ):
            return token
        return self._nearest(folded) or token

    def _is_known_or_prefix(self, folded: str) -> bool:
        if folded in self._vocab:
            return True
        index = bisect_left(self._prefix_words, folded)
        return index < len(self._prefix_words) and self._prefix_words[index].startswith(folded)

    def _nearest_uncached(self, folded: str) -> str | None:
        max_edits = (
            _SHORT_TOKEN_MAX_EDITS if len(folded) <= _SHORT_TOKEN_LENGTH else _LONG_TOKEN_MAX_EDITS
        )
        pool = [
            word
            for length in range(len(folded) - max_edits, len(folded) + max_edits + 1)
            for word in self._words_by_start_and_length.get((folded[0], length), ())
        ]
        matches = extract(
            folded,
            pool,
            scorer=DamerauLevenshtein.distance,
            score_cutoff=max_edits,
            limit=_CANDIDATE_LIMIT,
        )
        if not matches:
            return None
        best_distance = matches[0][1]
        closest = [word for word, distance, _ in matches if distance == best_distance]
        return max(closest, key=lambda word: self._vocab.get(word, 0))


@lru_cache(maxsize=1)
def get_default_query_corrector() -> QueryCorrector | None:
    """Return cached default QueryCorrector instance loaded from artifacts or data/."""
    corrector = QueryCorrector.load_packaged_lexicon()
    if corrector is not None:
        return corrector
    root = Path(__file__).resolve().parents[2]
    vocab_path = root / "data" / "vocab.tsv"
    lex_path = root / "data" / "query_lexicon.tsv.xz"
    if vocab_path.is_file():
        return QueryCorrector.from_file(
            vocab_path, lexicon_path=lex_path if lex_path.is_file() else None
        )
    return None


__all__ = [
    "QueryCorrector",
    "get_default_query_corrector",
    "iter_vocab_tokens",
    "load_lexicon",
    "load_vocab",
    "write_vocab",
]

"""Tests for the vocabulary-based query corrector and its engine integration."""

from __future__ import annotations

import lzma
from pathlib import Path

import pytest

from vihap.cleaners.vocab_corrector import (
    QueryCorrector,
    get_default_query_corrector,
    iter_vocab_tokens,
    load_vocab,
    write_vocab,
)

VOCAB = {
    "waterpoint": 500,
    "highlands": 9000,
    "coffee": 8000,
    "lumiere": 40,
    "nguyen": 90000,
    "trai": 4000,
    "tray": 300,
}


def test_iter_vocab_tokens_folds_diacritics_and_drops_numbers_and_singletons():
    assert list(iter_vocab_tokens("Cà Phê Đại La 12A, x")) == ["ca", "phe", "dai", "la"]


def test_unknown_token_is_corrected_to_nearest_vocabulary_word():
    corrector = QueryCorrector(VOCAB)
    assert corrector.correct("waterponit") == "waterpoint"


def test_transposition_and_substitution_typos_are_corrected_in_context():
    corrector = QueryCorrector(VOCAB)
    assert corrector.correct("highlnads lumuere") == "highlands lumiere"


def test_vocabulary_words_numbers_and_short_tokens_are_left_alone():
    corrector = QueryCorrector(VOCAB)
    assert corrector.correct("nguyen trai 12a ktx") == "nguyen trai 12a ktx"


def test_tie_on_distance_prefers_the_more_frequent_word():
    corrector = QueryCorrector({"hotel": 900, "hotal": 50})
    assert corrector.correct("hotsl") == "hotel"  # one edit from both; hotel is more common


def test_token_too_far_from_every_word_is_not_changed():
    corrector = QueryCorrector(VOCAB)
    assert corrector.correct("zzzzzzzz") == "zzzzzzzz"


def test_long_tokens_allow_two_edits_but_short_tokens_only_one():
    corrector = QueryCorrector({"coffee": 100, "highlands": 100})
    assert corrector.correct("hihglaxds") == "highlands"  # 2 edits, length 9
    assert corrector.correct("cofxxe") == "cofxxe"  # 2 edits, length 6


def test_rare_candidate_is_rejected_when_it_is_not_clearly_more_common():
    corrector = QueryCorrector({"abcdef": 1}, min_candidate_count=3)
    assert corrector.correct("abcdeg") == "abcdeg"


def test_first_letter_must_match_to_avoid_dropping_a_brand_prefix():
    corrector = QueryCorrector({"group": 5000})
    assert corrector.correct("pigroup") == "pigroup"


def test_tokens_shorter_than_the_minimum_length_are_never_corrected():
    assert QueryCorrector({"park": 5000}).correct("pank") == "pank"
    assert QueryCorrector({"park": 5000}, min_token_length=4).correct("pank") == "park"


def test_default_candidate_count_floor_rejects_rare_catalog_words():
    assert QueryCorrector({"hotelmeo": 3}).correct("hotelmex") == "hotelmex"
    assert QueryCorrector({"hotelmeo": 30}).correct("hotelmex") == "hotelmeo"


def test_brand_allowlist_qualifies_rare_brand_words():
    # 'starbux' has count 2 (< 30), so normally blocked; with brand_allowlist it is accepted
    vocab = {"starbucks": 2}
    corrector_no_brand = QueryCorrector(vocab, min_candidate_count=30)
    assert corrector_no_brand.correct("starbuckx") == "starbuckx"

    corrector_brand = QueryCorrector(
        vocab, min_candidate_count=30, brand_allowlist=frozenset(["starbucks"])
    )
    assert corrector_brand.correct("starbuckx") == "starbucks"


def test_token_that_is_a_prefix_of_a_vocabulary_word_is_left_alone():
    corrector = QueryCorrector({"waterpoint": 500, "waterbury": 90, "water": 4000})
    assert corrector.correct("waterpoin") == "waterpoin"  # typing in progress
    assert corrector.correct("waterbu") == "waterbu"  # would otherwise become "water"


def test_empty_and_whitespace_input_round_trip():
    corrector = QueryCorrector(VOCAB)
    assert corrector.correct("") == ""
    assert corrector.correct("   ") == "   "


def test_punctuation_spacing_and_alphanumeric_tokens_are_preserved():
    corrector = QueryCorrector(VOCAB)
    assert corrector.correct("so 5, waterponit  d5abcd") == "so 5, waterpoint  d5abcd"


def test_diacritic_words_found_in_vocabulary_keep_their_accents():
    corrector = QueryCorrector({"nguyen": 100})
    assert corrector.correct("Nguyễn") == "Nguyễn"


def test_vocab_file_round_trip(tmp_path: Path):
    path = tmp_path / "vocab.tsv"
    write_vocab(path, VOCAB)
    assert load_vocab(path) == VOCAB


def test_missing_vocab_file_raises(tmp_path: Path):
    with pytest.raises(FileNotFoundError):
        QueryCorrector.from_file(tmp_path / "absent.tsv")


def test_load_vocab_xz(tmp_path: Path):
    xz_path = tmp_path / "vocab.tsv.xz"
    content = b"highlands\t100\ncoffee\t200\n"
    xz_path.write_bytes(lzma.compress(content))
    assert load_vocab(xz_path) == {"highlands": 100, "coffee": 200}


def test_singleton_catalog_typo_does_not_shadow_user_typo():
    # 'highlads' has count 1 (spurious catalog typo); 'highlands' has count 9000.
    # User types 'highlad'. It must be corrected to 'highlands' and NOT shielded by 'highlads'.
    vocab = {"highlands": 9000, "highlads": 1}
    corrector = QueryCorrector(vocab, min_prefix_count=5)
    assert corrector.correct("highlad") == "highlands"


def test_canonical_targets_in_lexicon_are_protected_from_reverse_corruption():
    # Catalog only knows 'mcdonald' (typo with high count); lexicon maps 'mcdonald' -> 'mcdonalds'.
    # User types the valid canonical 'mcdonalds'. Corrector must NOT revert it back to 'mcdonald'.
    vocab = {"mcdonald": 500}
    lexicon = {"mcdonald": "mcdonalds"}
    corrector = QueryCorrector(vocab, lexicon=lexicon)
    assert corrector.correct("mcdonalds") == "mcdonalds"
    assert corrector.correct("to o mcdonald tran duy hung") == "to o mcdonalds tran duy hung"
    assert corrector.correct("to o mcdonalds tran duy hung") == "to o mcdonalds tran duy hung"


def test_multi_token_and_phrase_typo_correction_via_lexicon():
    # Lexicon contains compound phrase typo
    vocab = {"dcapitale": 500, "tran": 1000, "duy": 1000, "hung": 1000}
    lexicon = {"d capital": "dcapitale", "coffe house": "coffeehouse"}
    corrector = QueryCorrector(vocab, lexicon=lexicon)
    assert (
        corrector.correct("chung cu d capital tran duy hung") == "chung cu dcapitale tran duy hung"
    )
    assert corrector.correct("di uong coffe house") == "di uong coffeehouse"


def test_get_default_query_corrector_singleton():
    c1 = get_default_query_corrector()
    c2 = get_default_query_corrector()
    assert c1 is c2
    if c1 is not None:
        assert c1.correct("mcdonald tran duy hung") == "mcdonalds tran duy hung"
